        let mut step_a = make_step("a", "exit 1", vec![]);
        step_a.allow_failure = true;

        let mut steps = HashMap::new();
        steps.insert("a".to_string(), step_a);
        steps.insert(
            "b".to_string(),
            make_step(
                "b",
                &format!("touch {}", marker_b.display()),
                vec!["a".to_string()],
            ),
        );
        steps.insert(
            "c".to_string(),
            make_step(
                "c",
                &format!("touch {}", marker_c.display()),
                vec!["b".to_string()],
            ),
        );

