        let marker_b = temp.path().join("b.txt");
        let marker_c = temp.path().join("c.txt");

        let config: BivvyConfig = serde_yaml::from_str(
            r#"
            workflows:
              default:
                steps: [a, b, c]
        "#,
        )
        .unwrap();

