    #[test]
    fn workflow_result_aborted_defaults_false() {
        let result = WorkflowResult {
            workflow: "default".to_string(),
            steps: vec![],
            skipped: vec![],
            duration: Duration::from_secs(0),
            success: true,
            aborted: false,
