    fn make_step_with_check(
        name: &str,
        command: &str,
        check: Option<crate::config::CompletedCheck>,
    ) -> ResolvedStep {
        ResolvedStep {
            name: name.to_string(),
            title: name.to_string(),
            description: None,
            command: command.to_string(),
            depends_on: vec![],
            completed_check: check,
            precondition: None,
            skippable: true,
            required: false,
            prompt_if_complete: true,
            allow_failure: false,
            retry: 0,
            env: HashMap::new(),
            watches: vec![],
            before: vec![],
