            return;
        }

        println!();
        println!("  ┌─ Summary ──────────────────────────");

        for step in &summary.step_results {
            let icon = step.status.icon();
            let duration_str = step.duration.map(format_duration).unwrap_or_default();
            let detail_str = step.detail.as_deref().unwrap_or("");

            let right_side = if !duration_str.is_empty() {
                duration_str
            } else if !detail_str.is_empty() {
                detail_str.to_string()
            } else {
                String::new()
            };

            println!("  │ {} {:<20} {}", icon, step.name, right_side);
        }

        println!("  ├────────────────────────────────────");
        println!(
            "  │ Total: {} · {} run · {} skipped",
            format_duration(summary.total_duration),
            summary.steps_run,
            summary.steps_skipped,
        );
        println!("  └────────────────────────────────────");

        if summary.success {
            println!("  ✓ Setup complete!");
        } else {
            let status = StatusKind::Failed;
            eprintln!(
                "  {} Setup failed: {}",
                status.icon(),
                summary.failed_steps.join(", ")
            );
        }
    }

    fn is_interactive(&self) -> bool {
        false
    }

    fn set_output_mode(&mut self, mode: OutputMode) {
        self.mode = mode;
    }

    fn theme(&self) -> &BivvyTheme {
        &self.theme
    }

    fn create_line_callback(&self) -> Option<OutputCallback> {
        if self.mode == OutputMode::Verbose {
            let cb: OutputCallback = Box::new(|line: crate::shell::OutputLine| {
                let text = match &line {
                    crate::shell::OutputLine::Stdout(s) => s.trim_end(),
                    crate::shell::OutputLine::Stderr(s) => s.trim_end(),
                };
                if !text.is_empty() {
                    println!("      {text}");
                }
            });
            Some(cb)
        } else {
            None
        }
    }
}

